foundation.solution_text:
At $x = 1$: $y = \sqrt{0} + 2 = 2 \implies (1, 2)$
At $x = 2$: $y = \sqrt{1} + 2 = 3 \implies (2, 3)$
At $x = 5$: $y = \sqrt{4} + 2 = 4 \implies (5, 4)$
At $x = 10$: $y = \sqrt{9} + 2 = 5 \implies (10, 5)$
Plotted points: $(1, 2), (2, 3), (5, 4), (10, 5)$
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.6]
\draw[->] (-0.8,0) -- (11.5,0) node[right] {$x$};
\draw[->] (0,-0.8) -- (0,6.5) node[above] {$y$};
\foreach \x in {1,...,11} {\draw (\x,0.15) -- (\x,-0.15); \node[below,font=\scriptsize] at (\x,-0.15) {$\x$};}
\foreach \y in {1,...,6} {\draw (0.15,\y) -- (-0.15,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\y$};}
\node[below left,font=\scriptsize] at (0,0) {$0$};
\draw[thick,-{Stealth}] plot[domain=0:3.2,samples=101,smooth,variable=\t] ({1+\t*\t},{2+\t});
\fill (1,2) circle (3pt) node[below right] {$(1, 2)$};
\fill (2,3) circle (2pt);
\fill (5,4) circle (2pt);
\end{tikzpicture}
[/tikz]

